import{_ as a,H as n,f as t,i as p}from"./chunks/framework.nyB-Xt5O.js";const g=JSON.parse('{"title":"费米估算 (Fermi Estimation)","description":"","frontmatter":{},"headers":[],"relativePath":"interview/ip-4-case-study/04-fermi-estimation.md","filePath":"interview/ip-4-case-study/04-fermi-estimation.md","lastUpdated":1779798726000}'),e={name:"interview/ip-4-case-study/04-fermi-estimation.md"};function i(l,s,d,o,r,c){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="费米估算-fermi-estimation" tabindex="-1">费米估算 (Fermi Estimation) <a class="header-anchor" href="#费米估算-fermi-estimation" aria-label="Permalink to &quot;费米估算 (Fermi Estimation)&quot;">​</a></h1><blockquote><p>费米估算题是数据分析面试中的经典题型，考察候选人的逻辑拆解能力、数量级敏感度和假设合理性。题目通常看起来无从下手（如&quot;北京有多少个加油站&quot;），但通过合理的逻辑链条和近似，可以得到一个数量级正确的估计。</p></blockquote><h2 id="核心方法论" tabindex="-1">核心方法论 <a class="header-anchor" href="#核心方法论" aria-label="Permalink to &quot;核心方法论&quot;">​</a></h2><h3 id="估算公式" tabindex="-1">估算公式 <a class="header-anchor" href="#估算公式" aria-label="Permalink to &quot;估算公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>答案 = 已知量 × 合理假设的乘积</span></span></code></pre></div><h3 id="四大原则" tabindex="-1">四大原则 <a class="header-anchor" href="#四大原则" aria-label="Permalink to &quot;四大原则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>逻辑拆解</td><td>将复杂问题拆解为可估算的子问题</td></tr><tr><td>合理假设</td><td>每个假设都要有依据（经验值/常识/类比）</td></tr><tr><td>数量级正确</td><td>不追求精确，确保在 10 倍以内即可</td></tr><tr><td>交叉验证</td><td>用不同方法估算同一个值，看是否吻合</td></tr></tbody></table><h3 id="常用参考值" tabindex="-1">常用参考值 <a class="header-anchor" href="#常用参考值" aria-label="Permalink to &quot;常用参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>参考值</th></tr></thead><tbody><tr><td>中国人口</td><td>14 亿</td></tr><tr><td>北京人口</td><td>~2200 万</td></tr><tr><td>上海人口</td><td>~2500 万</td></tr><tr><td>家庭平均规模</td><td>~3 人</td></tr><tr><td>小汽车保有量（中国）</td><td>~3 亿</td></tr><tr><td>每人日均用水</td><td>~150L</td></tr><tr><td>每人日均餐饮消费</td><td>~50 元</td></tr><tr><td>便利店日均客流</td><td>~500 人</td></tr></tbody></table><hr><h2 id="案例-1-北京有多少个加油站" tabindex="-1">案例 1：北京有多少个加油站？ <a class="header-anchor" href="#案例-1-北京有多少个加油站" aria-label="Permalink to &quot;案例 1：北京有多少个加油站？&quot;">​</a></h2><p><strong>思路拆解</strong>：</p><p>北京需要加油站的车辆数 / 每个加油站能服务的车辆数</p><p><strong>Step 1: 估算北京汽车数量</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京人口 ≈ 2200 万</span></span>
<span class="line"><span>家庭平均人数 ≈ 3 人/户</span></span>
<span class="line"><span>家庭总数 ≈ 2200 / 3 ≈ 730 万户</span></span>
<span class="line"><span></span></span>
<span class="line"><span>假设 60% 家庭有车，加上出租车/网约车/货车 ≈ 50 万辆</span></span>
<span class="line"><span>北京汽车总数 ≈ 730 × 60% + 50 ≈ 490 万辆</span></span>
<span class="line"><span></span></span>
<span class="line"><span>交叉验证：北京机动车保有量官方数据 ≈ 600 万辆（含摩托车等）</span></span>
<span class="line"><span>取 500 万辆作为工作值。</span></span></code></pre></div><p><strong>Step 2: 估算每辆车的加油频率</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设平均每辆车每两周（14 天）加一次油</span></span>
<span class="line"><span>每辆车年加油次数 = 365 / 14 ≈ 26 次/年</span></span></code></pre></div><p><strong>Step 3: 估算每个加油站的日服务能力</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个加油站假设有 4 个加油位</span></span>
<span class="line"><span>每个加油位加一次油 ≈ 5 分钟（含排队等待）</span></span>
<span class="line"><span>加油站营业时间 ≈ 16 小时/天（早 7 点到晚 11 点）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每天最多服务车辆 = 4 个加油位 × (16小时 × 60分钟 / 5分钟)</span></span>
<span class="line"><span>= 4 × 192 ≈ 768 辆/天</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实际利用率 ≈ 60%（不是所有时间都满负荷）</span></span>
<span class="line"><span>每个加油站日均实际服务 ≈ 768 × 60% ≈ 460 辆/天</span></span></code></pre></div><p><strong>Step 4: 计算加油站数量</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京每天需要加油的车辆数 = 500 万 / 14 = 35.7 万辆/天</span></span>
<span class="line"><span>需要的加油站数 = 35.7 万 / 460 ≈ **776 个**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>加上郊区/高速公路上的加油站，大约 800-1000 个</span></span></code></pre></div><p><strong>答案范围</strong>：约 800-1200 个。</p><p><strong>实际参考</strong>：北京加油站约 1100 个左右（数据来源：商务部）。</p><hr><h2 id="案例-2-上海星巴克有多少家" tabindex="-1">案例 2：上海星巴克有多少家？ <a class="header-anchor" href="#案例-2-上海星巴克有多少家" aria-label="Permalink to &quot;案例 2：上海星巴克有多少家？&quot;">​</a></h2><p><strong>思路拆解</strong>：从需求和供给两个角度交叉验证。</p><p><strong>方法一：从需求角度（人均法）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上海人口 ≈ 2500 万</span></span>
<span class="line"><span>假设每天喝咖啡的人群比例 ≈ 15%（一线城市咖啡渗透率）</span></span>
<span class="line"><span>每天喝咖啡的人数 ≈ 2500 × 15% = 375 万人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>假设其中 40% 选择星巴克 ≈ 150 万人/天</span></span>
<span class="line"><span>平均每个用户每天服务客数？星巴克单店日均 ≈ 400-600 杯</span></span>
<span class="line"><span>单店日均服务咖啡消费者 ≈ 200 人（算上 share 和非咖啡消费者）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>星巴克数量 = 150 万 / 200 ≈ **750 家**</span></span></code></pre></div><p><strong>方法二：从供给角度（面积法）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上海面积 ≈ 6340 平方公里</span></span>
<span class="line"><span>假设核心城区（浦西七区 + 浦东核心）≈ 1000 平方公里</span></span>
<span class="line"><span>星巴克覆盖主要在核心城区和商圈</span></span>
<span class="line"><span></span></span>
<span class="line"><span>取每 3 平方公里一家星巴克（核心区更密，郊区更疏）</span></span>
<span class="line"><span>核心城区星巴克 ≈ 1000 / 3 ≈ 333 家</span></span>
<span class="line"><span>郊区按核心城区的 30% ≈ 100 家</span></span>
<span class="line"><span>加上交通枢纽/景点 ≈ 50 家</span></span>
<span class="line"><span></span></span>
<span class="line"><span>估测 ≈ 333 + 100 + 50 ≈ **480 家**（偏保守）</span></span></code></pre></div><p><strong>综合估计</strong>：取两种方法的中间值，约 600-700 家。</p><p><strong>实际参考</strong>：上海星巴克约 900+家（全球星巴克最多的城市）。</p><hr><h2 id="案例-3-北京地铁一天的客运量是多少" tabindex="-1">案例 3：北京地铁一天的客运量是多少？ <a class="header-anchor" href="#案例-3-北京地铁一天的客运量是多少" aria-label="Permalink to &quot;案例 3：北京地铁一天的客运量是多少？&quot;">​</a></h2><p><strong>思路拆解</strong>：按线路×班次×载客量的方法。</p><p><strong>Step 1: 估算运营线路和班次</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京地铁运营线路 ≈ 27 条</span></span>
<span class="line"><span>假设平均每条线路双向运营，高峰期 2 分钟一班，平峰期 5 分钟一班</span></span>
<span class="line"><span>平均间隔 ≈ 3.5 分钟</span></span>
<span class="line"><span>单方向每小时班次 ≈ 60 / 3.5 ≈ 17 班</span></span>
<span class="line"><span>每天运营时间 ≈ 19 小时（早 5 点到凌晨 0 点）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高峰时段 ≈ 4 小时（早 7-9，晚 17-19）</span></span>
<span class="line"><span>平峰时段 ≈ 15 小时</span></span></code></pre></div><p><strong>Step 2: 估算每列车载客量</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一列地铁 ≈ 6 节车厢</span></span>
<span class="line"><span>每节车厢 ≈ 200 人（拥挤时）</span></span>
<span class="line"><span>满载率 ≈ 70%（平峰）到 120%（高峰）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高峰每列车 ≈ 6 × 200 × 120% ≈ 1440 人</span></span>
<span class="line"><span>平峰每列车 ≈ 6 × 200 × 70% ≈ 840 人</span></span></code></pre></div><p><strong>Step 3: 计算单线日客运量</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高峰 4 小时 × 17 班/小时 × 1440 人/单方向 × 2 方向 = 195,840 人</span></span>
<span class="line"><span>平峰 15 小时 × 17 班/小时 × 840 人/单方向 × 2 方向 = 428,400 人</span></span>
<span class="line"><span>单线日客运量 ≈ 62 万人次/条</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但实际不同线路差异大（1 号线 vs 郊区线）</span></span>
<span class="line"><span>加权平均取 60% 的满载率水平 ≈ 37 万人次/条/日</span></span></code></pre></div><p><strong>Step 4: 总量估算</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京地铁日客运量 ≈ 27 条 × 37 万 ≈ **1000 万人次/日**</span></span></code></pre></div><p><strong>实际参考</strong>：北京地铁日客运量在 1000-1300 万人次之间。估算在正确数量级。</p><hr><h2 id="其他经典费米估问题" tabindex="-1">其他经典费米估问题 <a class="header-anchor" href="#其他经典费米估问题" aria-label="Permalink to &quot;其他经典费米估问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题目</th><th>核心拆解思路</th><th>参考答案范围</th></tr></thead><tbody><tr><td>中国一年消耗多少瓶可乐？</td><td>人均 × 人口 × 频率</td><td>约 600-800 亿瓶</td></tr><tr><td>北京有多少个理发店？</td><td>人口 / 每个理发师服务用户数</td><td>约 2-3 万个</td></tr><tr><td>上海每天产生多少吨垃圾？</td><td>人均 × 人口</td><td>约 2-3 万吨</td></tr><tr><td>一架波音 747 能装多少个乒乓球？</td><td>机舱体积 / 乒乓球体积 × 填充率</td><td>约 5000 万个</td></tr><tr><td>抖音一天的用户使用总时长？</td><td>DAU × 人均使用时长</td><td>约 10-15 亿小时</td></tr><tr><td>中国一年消耗多少张 A4 纸？</td><td>办公人均 × 白领人数 + 学校用量</td><td>约 2000-3000 亿张</td></tr></tbody></table><h2 id="估算技巧总结" tabindex="-1">估算技巧总结 <a class="header-anchor" href="#估算技巧总结" aria-label="Permalink to &quot;估算技巧总结&quot;">​</a></h2><ol><li><strong>记住关键基数</strong>：中国人口 14 亿、北京人口 2200 万、平均家庭 3 人</li><li><strong>从大到小拆解</strong>：先用人数、再用比例、再用频次</li><li><strong>多方法交叉验证</strong>：从供给侧估一次，从需求侧估一次</li><li><strong>不要在一处精确</strong>：每个环节保持 2 倍以内的精度即可，最终数量级正确</li><li><strong>边算边复查</strong>：结果是否合理？是否符合常识？</li><li><strong>大声说出你的思考过程</strong>：面试官更看重逻辑链条，而非最终数字</li></ol><h2 id="自测题" tabindex="-1">自测题 <a class="header-anchor" href="#自测题" aria-label="Permalink to &quot;自测题&quot;">​</a></h2><ol><li>估算上海迪士尼一年的客流量</li><li>估算北京首都机场一天的起降架次</li><li>估算全中国一年消耗多少杯奶茶</li><li>估算美团外卖一天的订单量</li><li>估算微信一天发送的消息数量</li></ol>`,51)])])}const b=a(e,[["render",i]]);export{g as __pageData,b as default};
